const state={data:null,minutes:40,page:'focus',timer:null,selectedReward:null,selectedSpecies:null,plantMode:'basic',period:'all',catalogTier:'basic',systemStatus:null,recentContext:{notes:null,revision:0,editingId:null},taskCalendar:{data:null,mode:'week',selectedDate:null,activeContext:[]},nextAction:{active:null,pendingGeneration:false,pendingResponse:null,reportPath:null,generation:null,generationTimer:null,generationPolling:false,generationPollAt:0},goal:{data:null,plan:null,view:'overview',busy:false}};
