function navigate(page){state.page=page;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));$('#pageTitle').textContent=titles[page];$('#sidebar').classList.remove('open');$('#taskRefresh').classList.toggle('hidden',page!=='tasks');if(page==='garden')return renderGarden();if(page==='next-action')return loadNextActionPanel();if(page==='recent-context')return loadRecentContext();if(page==='tasks')return loadTasks();if(page==='goal')return loadGoalMode();if(page==='settings')return loadSystemStatus();}
