function healthAge(seconds){if(seconds===null||seconds===undefined)return'暂无时间';if(seconds<60)return'刚刚更新';if(seconds<3600)return`${Math.floor(seconds/60)} 分钟前`;return`${Math.floor(seconds/3600)} 小时前`}
