function renderNextAction(data){clearNextActionGeneration();state.nextAction.active=data;const evidence=Array.isArray(data.evidence_points)?data.evidence_points.slice(0,4):[];const card=$('#nextActionSuggestion');card.innerHTML=`<div class="next-action-title"><div><p class="eyebrow">A SMALL, REAL START</p><h2>${escapeHtml(data.title||'当前建议')}</h2></div><div class="next-action-pills"><span>${data.source==='course_schedule'?'课表提示':escapeHtml(data.duration_minutes)+' 分钟'}</span><span>${escapeHtml(data.decision_type||'行动')}</span></div></div><div class="next-action-first-step"><span>当前最后版本 · 先做这一件</span><strong>${escapeHtml(data.first_step||'')}</strong></div><div class="next-action-copy"><h3>为什么是现在</h3><p>${escapeHtml(data.reason_short||'')}</p><p>${escapeHtml(data.persuasive_explanation||'')}</p></div><div class="next-action-evidence"><h3>花园看到的线索</h3>${evidence.length?`<ul>${evidence.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p>这次没有可展示的线索。</p>'}</div><div class="next-action-reduced"><span>如果现在还是难</span><p>${escapeHtml(data.reduced_version||'')}</p></div>`;$('#nextActionFeedback').classList.toggle('hidden',!data.suggestion_id||data.source==='course_schedule');if(data.suggestion_id&&data.source!=='course_schedule')renderNextActionClarification(data);showNextActionLogin(false)}
