function openPlant(id){openPlantTabbed(id)}
function closePlant(){$('#plantModal').classList.add('hidden');state.selectedReward=null;state.selectedSpecies=null;state.plantMode='basic'}
function bindGardenPlantTips(){const grid=$('#gardenGrid');if(!grid)return;const closeAll=()=>$$('.garden-plant.is-tip-open').forEach(plant=>{plant.classList.remove('is-tip-open');plant.setAttribute('aria-expanded','false')});const toggle=plant=>{const open=plant.classList.contains('is-tip-open');closeAll();if(!open){plant.classList.add('is-tip-open');plant.setAttribute('aria-expanded','true')}};grid.addEventListener('click',event=>{const plant=event.target.closest('.garden-plant');if(plant){event.stopPropagation();toggle(plant)}else closeAll()});document.addEventListener('click',event=>{if(!event.target.closest('#gardenIsland'))closeAll()})}
async function plant(){try{$('#plantConfirm').disabled=true;const exchange=state.plantMode==='advanced-exchange',directAdvanced=!exchange&&state.data.reward_history.find(r=>r.id===state.selectedReward)?.tier==='advanced';await api(exchange?'/api/rewards/advanced-plant':`/api/rewards/${encodeURIComponent(state.selectedReward)}/plant`,{method:'POST',body:JSON.stringify({species_id:state.selectedSpecies})});closePlant();await load();toast(exchange?'已消耗 3 次初级机会，种下高级植物！':directAdvanced?'每日挑战奖励已种成高级植物！':'初级植物已经种下了');navigate('garden')}catch(e){toast(e.message,true);$('#plantConfirm').disabled=false}}
async function load(){state.data=await api('/api/bootstrap');render();if(state.page==='settings')loadSystemStatus()}
async function sync(){const btn=$('#syncBtn');btn.classList.add('loading');$('#syncText').textContent='同步中';try{const result=await api('/api/rewards/sync',{method:'POST',body:'{}'});await load();toast(result.inserted?`新增 ${result.inserted} 份奖励`:'奖励已是最新')}catch(e){toast(e.message,true)}finally{btn.classList.remove('loading');$('#syncText').textContent='同步奖励'}}
function bind(){$$('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#syncBtn').onclick=sync;$('#modalClose').onclick=closePlant;$('#plantModal').onclick=e=>{if(e.target.id==='plantModal')closePlant()};$('#plantConfirm').onclick=plant;$('#plantBasicMenu').onclick=openBasicPlanting;$('#plantAdvancedMenu').onclick=openAdvancedPlanting;$$('#presetRow button').forEach(b=>b.onclick=()=>{$$('#presetRow button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.minutes=Number(b.dataset.minutes);updateIdleTimer()});$$('.period-tabs button').forEach(b=>b.onclick=()=>{$$('.period-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.period=b.dataset.period;renderGarden()});$('#nextActionGenerate').onclick=()=>generateNextAction();$('#nextActionLoad').onclick=loadNextActionActive;$('#nextActionLoginBtn').onclick=loginNextAction;$('#nextActionAccept').onclick=()=>saveNextActionResponse('accepted');$('#nextActionClarify').onclick=openNextActionClarification;$('#nextActionClarifySubmit').onclick=submitNextActionClarification;$('#nextActionAlternative').onclick=()=>{$('#nextActionReasonBox').classList.remove('hidden');state.nextAction.pendingResponse='alternative_requested'};$('#nextActionDecline').onclick=()=>{$('#nextActionReasonBox').classList.remove('hidden');state.nextAction.pendingResponse='declined'};$('#nextActionReasonSubmit').onclick=()=>saveNextActionResponse(state.nextAction.pendingResponse,true);$$('[data-next-outcome]').forEach(button=>button.onclick=()=>saveNextActionOutcome(button.dataset.nextOutcome));$('#nextActionReportSubmit').onclick=submitNextActionReportFeedback;$('#nextActionIssueSubmit').onclick=submitNextActionIssue;$('#scheduleBtn').onclick=createSchedule;$('#cycleBtn').onclick=createContinuousFocus;$('#taskSave').onclick=saveTask;$('#taskClear').onclick=clearTaskForm;$('#taskRefresh').onclick=loadTasks;$$('[data-task-view]').forEach(button=>button.onclick=()=>setTaskView(button.dataset.taskView));$$('[data-calendar-mode]').forEach(button=>button.onclick=()=>setCalendarMode(button.dataset.calendarMode));$('#rcSave').onclick=saveRecentContext;$('#rcRefresh').onclick=loadRecentContext}
bind();$('#calendarModalClose').onclick=()=>closeCalendarDayModal();$('#calendarModal').onclick=event=>{if(event.target.id==='calendarModal')closeCalendarDayModal()};document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#calendarModal').classList.contains('hidden'))closeCalendarDayModal()});$('#systemStatusRefresh').onclick=loadSystemStatus;bindGardenPlantTips();load().then(()=>sync()).catch(e=>toast(e.message,true));

// The main action is deliberately dual-device.  Single-device execution is
// available only from the small "more" menu, never from shadow intervention.
state.targets=['windows','phone'];
state.focusTask=null;
function focusTargetLabel(){const labels={windows:'\u7535\u8111',phone:'\u624b\u673a'};return state.targets.length?state.targets.map(x=>labels[x]).join('\uff0b'):'\u4e0d\u9501\u673a'}
function setFocusTask(task){state.focusTask=task||null;const label=task?(task.title||'\u672a\u547d\u540d\u4efb\u52a1'):'\u4e0d\u5173\u8054\u4efb\u52a1';$('#focusTaskPicker').querySelector('span').textContent=label;$('#focusTaskPanel').classList.add('hidden')}
function focusTaskOptions(effective){const groups=effective?.tasks||{},items=['overdue','today','near_term','later','recurring'].flatMap(group=>groups[group]||[]);const seen=new Set(),chosen=[];for(const task of items){if(!task?.task_id||seen.has(task.task_id))continue;seen.add(task.task_id);chosen.push(task);if(chosen.length>=10)break}const list=$('#focusTaskList');if(!chosen.length){list.innerHTML='<p>\u6682\u65e0\u53ef\u5173\u8054\u7684\u5f85\u529e\u3002</p>';return}list.innerHTML=chosen.map(task=>`<button class="focus-task-choice" type="button" data-focus-task="${encodeURIComponent(task.task_id)}"><b>${escapeHtml(task.title||'\u672a\u547d\u540d\u4efb\u52a1')}</b><small>${task.tomatoes_total!=null?`\ud83c\udf45 ${task.tomatoes_completed||0}/${task.tomatoes_total}`:'\u672a\u8bbe \ud83c\udf45 \u9884\u4f30\uff0c\u4ec5\u8bb0\u5f55\u5173\u8054'}</small></button>`).join('');$$('[data-focus-task]').forEach(button=>button.onclick=()=>{const id=decodeURIComponent(button.dataset.focusTask);setFocusTask(chosen.find(task=>task.task_id===id)||null)})}
async function openFocusTaskPicker(){const panel=$('#focusTaskPanel');panel.classList.toggle('hidden');if(panel.classList.contains('hidden'))return;try{focusTaskOptions(await api('/api/tasks'))}catch(error){$('#focusTaskList').innerHTML=`<p>\u4efb\u52a1\u6682\u4e0d\u53ef\u7528\uff1a${escapeHtml(error.message)}</p>`}}
startFocusWithTargets=async function(){const duration=state.minutes,destination=focusTargetLabel(),task=state.focusTask,association=task?`\n\u5173\u8054\u4efb\u52a1\uff1a${task.title||'\u672a\u547d\u540d\u4efb\u52a1'}`:'\n\u4e0d\u5173\u8054\u4efb\u52a1',lockNote=state.targets.length?'\u5df2\u5f00\u59cb\u7684\u9501\u5b9a\u901a\u5e38\u65e0\u6cd5\u63d0\u524d\u89e3\u9664\u3002':'\u672c\u6b21\u4ec5\u8ba1\u65f6\uff0c\u4e0d\u4f1a\u9501\u5b9a\u8bbe\u5907\u3002';if(!confirm(`\u5c06\u5f00\u59cb ${duration} \u5206\u949f\u4e13\u6ce8\uff0c${destination}\u3002${association}\n${lockNote}\n\u662f\u5426\u7ee7\u7eed\uff1f`))return;try{$('#startBtn').disabled=true;await api('/api/focus/start',{method:'POST',body:JSON.stringify({duration,profile_id:$('#profileSelect').value,targets:state.targets,task_id:task?.task_id||null,task_title:task?.title||null,source:'garden'})});await load();toast(`\u4e13\u6ce8\u5df2\u5165\u56ed\uff1a${destination}${task?' \u00b7 \u5df2\u5173\u8054\u4efb\u52a1':''}`)}catch(error){toast(error.message,true)}finally{$('#startBtn').disabled=false}}
async function startFocusWithTargets(){
  const duration=state.minutes;
  const labels={windows:'电脑',phone:'手机'};
  const destination=state.targets.map(x=>labels[x]).join('＋');
  if(!confirm(`将开始 ${duration} 分钟专注，并介入：${destination}。已开始的锁定通常无法提前解除。是否继续？`))return;
  try{
    $('#startBtn').disabled=true;
    await api('/api/focus/start',{method:'POST',body:JSON.stringify({duration,profile_id:$('#profileSelect').value,targets:state.targets})});
    await load();toast(`专注已入队：${destination}`);
  }catch(error){toast(error.message,true)}finally{$('#startBtn').disabled=false}
}
async function createSchedule(){
  const raw=$('#scheduleAt').value;
  if(!raw){toast('请先选择预约开始时间',true);return}
  const startsAt=new Date(raw).toISOString();
  if(!confirm(`预约在 ${raw.replace('T',' ')} 开始 ${state.minutes} 分钟专注，并介入当前所选设备。是否继续？`))return;
  try{await api('/api/focus/schedule',{method:'POST',body:JSON.stringify({duration:state.minutes,profile_id:$('#profileSelect').value,targets:state.targets,starts_at:startsAt})});await load();toast('预约专注已创建')}catch(error){toast(error.message,true)}
}
async function createContinuousFocus(){
  const focusMinutes=Number($('#cycleFocusMinutes').value),restMinutes=Number($('#cycleRestMinutes').value),rounds=Number($('#cycleRounds').value);
  if(!confirm(`将开始 ${rounds} 轮：每轮专注 ${focusMinutes} 分钟，休息 ${restMinutes} 分钟。休息时不会解除已经开始的锁定。是否继续？`))return;
  try{await api('/api/focus/continuous',{method:'POST',body:JSON.stringify({focus_minutes:focusMinutes,rest_minutes:restMinutes,rounds,profile_id:$('#profileSelect').value,targets:state.targets})});await load();toast('连续专注已创建，第一轮即将开始')}catch(error){toast(error.message,true)}
}
$('#startBtn').onclick=startFocusWithTargets;
$('#targetMore').onclick=()=>$('#targetMenu').classList.toggle('hidden');
$('#focusTaskPicker').onclick=openFocusTaskPicker;
$('#focusTaskClear').onclick=()=>setFocusTask(null);
$$('[data-focus-target]').forEach(button=>button.onclick=()=>{
  state.targets=button.dataset.focusTarget?button.dataset.focusTarget.split(','):[];
  $('#targetMenu').classList.add('hidden');
  $('#startBtn').textContent=state.targets.length===2?'开始专注 · 电脑＋手机':`开始专注 · 仅${state.targets[0]==='windows'?'电脑':'手机'}`;
});

function controlDate(value){
  if(!value)return '尚未冻结';
  const parsed=new Date(value);
  return Number.isNaN(parsed.getTime())?'尚未冻结':parsed.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
}
function controlMetricValue(value){
  if(value===null||value===undefined||Number.isNaN(Number(value)))return '—';
  const numeric=Number(value);
  return Number.isInteger(numeric)?String(numeric):numeric.toFixed(1);
}
async function syncControlStatus(){
  const button=$('#controlSyncBtn');
  if(!button)return;
  button.disabled=true;
  button.textContent='同步中…';
  try{
    const control=await api('/api/control/sync',{method:'POST',body:'{}'});
    state.systemStatus={...(state.systemStatus||{}),control};
    renderSystemStatus();
    toast(control.snapshot_state==='synced_live'?'状态数据已同步，本周决策保持冻结':'状态数据已同步，等待下次周评审');
  }catch(error){
    toast(`状态同步失败：${error.message}`,true);
  }finally{
    const current=$('#controlSyncBtn');
    if(current){current.disabled=false;current.textContent='同步状态'}
  }
}
function renderControlReview(control){
  const root=$('#controlReview');
  if(!root)return;
  if(!control||!control.state){
    root.innerHTML='<article class="pixel-panel control-state-card control-tone-unknown"><div class="control-state-code">S?</div><div class="control-state-copy"><p class="eyebrow">WEEKLY CONTROL</p><h2>控制快照尚未生成</h2><p>每日推迟债务与周级基线正在建立；现有硬规则不会因此改变。</p></div></article>';
    return;
  }
  const snapshot=control.snapshot_state==='frozen'?'已冻结':control.snapshot_state==='synced_live'?'数据已同步 · 决策冻结':control.snapshot_state==='synced_preview'?'数据已同步 · 待周评审':'临时预览';
  const tone=['stable','plan','attention','risk','unknown'].includes(control.state.tone)?control.state.tone:'unknown';
  const evidence=(control.state.evidence||[]).slice(0,3).map(item=>`<li>${escapeHtml(item)}</li>`).join('')||'<li>没有触发显著变化阈值。</li>';
  const qualityLabels={high:'可靠',medium:'代理',low:'低样本',collecting:'积累中'};
  const metrics=(control.metrics||[]).map(metric=>{
    const quality=['high','medium','low','collecting'].includes(metric.quality)?metric.quality:'low';
    const baseline=metric.baseline===null||metric.baseline===undefined?'基线积累中':`基线 ${controlMetricValue(metric.baseline)} ${escapeHtml(metric.unit||'')}`;
    const delta=metric.delta_percent===null||metric.delta_percent===undefined?'':` · ${Number(metric.delta_percent)>=0?'+':''}${controlMetricValue(metric.delta_percent)}%`;
    return`<article class="control-metric"><div class="control-metric-head"><span class="control-metric-id">${escapeHtml(metric.id||'?')}</span><span class="control-quality quality-${quality}">${qualityLabels[quality]}</span></div><h3>${escapeHtml(metric.label||'未命名指标')}</h3><div class="control-metric-value">${controlMetricValue(metric.value)} <small>${escapeHtml(metric.unit||'')}</small></div><p class="control-metric-compare">${baseline}${delta}</p><p class="control-metric-coverage">${escapeHtml(metric.role||'诊断')} · ${escapeHtml(metric.coverage||'未提供覆盖说明')}</p></article>`;
  }).join('');
  const ai=control.ai||{},windowData=control.window||{},currentWindow=windowData.current||{},baselineWindow=windowData.baseline||{},policy=control.policy||{};
  root.innerHTML=`<article class="pixel-panel control-state-card control-tone-${tone}"><div class="control-state-code">${escapeHtml(control.state.code||'S?')}</div><div class="control-state-copy"><p class="eyebrow">WEEKLY CONTROL · ${snapshot}</p><h2>${escapeHtml(control.state.name||'未判定')}</h2><p>${escapeHtml(control.state.summary||'')}</p></div><div class="control-freeze"><small>策略冻结至</small><b>${controlDate(control.frozen_until)}</b><button id="controlSyncBtn" class="control-sync-button" type="button" title="重新汇总当前指标并更新今日 D；不会改写冻结中的周结论">同步状态</button></div></article><div class="control-decision-row"><article class="pixel-panel control-adjustment"><p class="eyebrow">ONE CHANGE ONLY</p><h3>本周期唯一调整</h3><p>${escapeHtml(control.state.single_adjustment||'本周期不调整核心参数。')}</p></article><article class="pixel-panel control-evidence"><p class="eyebrow">EVIDENCE</p><h3>识别证据</h3><ol>${evidence}</ol></article></div><div class="control-metrics">${metrics||'<article class="pixel-panel control-empty">还没有主指标。</article>'}</div><div class="control-aux"><article class="pixel-panel control-ai"><p class="eyebrow">AI STRUCTURE · 辅助诊断</p><h3>AI 用途结构</h3><div class="control-ai-values"><span>任务相关<b>${controlMetricValue(ai.task_minutes)} min</b></span><span>游离使用<b>${controlMetricValue(ai.free_minutes)} min</b></span><span>未判定<b>${controlMetricValue(ai.unknown_minutes)} min</b></span></div></article><article class="pixel-panel control-policy"><p class="eyebrow">CONTROL BOUNDARY</p><h3>控制边界</h3><p>${escapeHtml(policy.note||'只读识别；不自动改变硬规则。')}</p></article></div><p class="control-window">当前 ${escapeHtml(currentWindow.start||'—')}—${escapeHtml(currentWindow.end||'—')}（${Number(currentWindow.report_days||0)}/7 日报） · 基线 ${escapeHtml(baselineWindow.start||'—')}—${escapeHtml(baselineWindow.end||'—')}（${Number(baselineWindow.report_days||0)} 日报）${control.synced_at?` · 最近同步 ${controlDate(control.synced_at)}`:''}</p>`;
  const syncButton=$('#controlSyncBtn');
  if(syncButton)syncButton.onclick=syncControlStatus;
}
const renderOperationalSystemStatus=renderSystemStatus;
renderSystemStatus=function(){renderOperationalSystemStatus();renderControlReview(state.systemStatus?.control)};

// Goal mode stays independent from Next Action.  It only shares the existing
// task-sync protocol after the user explicitly accepts a recommended day.
const goalToneLabels={unknown:'待核验',on_track:'正常',at_risk:'有风险',off_track:'偏离',achieved:'已达成',known:'已建立'};
const goalStatusLabels={planned:'计划中',in_progress:'进行中',blocked:'受阻',completed:'已完成'};
const goalInputLabels={ready:'可安排',awaiting_course_progress:'待填写授课进度',awaiting_material:'资料待同步'};
const goalMasteryLabels={0:'0 · 未接触',1:'1 · 听过/能看材料',2:'2 · 能复述定义定理',3:'3 · 能独立证明或解题'};
function goalRequestId(prefix='goal'){const id=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;return`${prefix}-${id}`}
function goalSetStatus(message,bad=false){const el=$('#goalStatus');if(!el)return;el.textContent=message;el.classList.toggle('bad',bad)}
function goalDate(value){if(!value)return'待定';try{return new Date(`${value}T12:00:00`).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}catch{return value}}
function goalMinutes(value){const minutes=Number(value)||0;return minutes>=60?`${(minutes/60).toFixed(minutes%60?1:0)} 小时`:`${minutes} 分钟`}
function goalRatio(value){return value===null||value===undefined?'待核验':`${Math.round(Number(value)*100)}%`}
function goalView(view){state.goal.view=view;$$('[data-goal-view]').forEach(button=>button.classList.toggle('active',button.dataset.goalView===view));$$('.goal-view').forEach(panel=>panel.classList.toggle('active',panel.id===`goal-view-${view}`))}
function goalTrackDetail(track){const mastery=track.mastery||{};if(track.code==='courses'){return Object.entries(track.course_scenarios||{}).map(([course,item])=>{const required=item.required_remaining_average===null||item.required_remaining_average===undefined?'尚无成绩，暂不计算剩余均分':`剩余需均分 ${item.required_remaining_average}`;const profile=item.profile_status==='confirmed'?'档案已确认':'档案部分确认';const progress=item.progress||{};return`${course}：${profile} · 已确认 ${progress.confirmed_taught_units||0}/${progress.total_units||0} 个小节 · ${required}`}).join('<br>')}if(track.code==='amss_exam')return`限时记录 ${mastery.attempt_count||0} 次 · 不同真实题源连续达标 ${mastery.consecutive_distinct_passes||0}/3`;if(track.code==='ergodic'){const d=mastery.deliverables||{};return`范围 ${d.reading_scope_confirmed?'✓':'待确认'} · 3–5 页笔记 ${d.note_3_to_5_pages?'✓':'—'} · 20–30 分钟讲解 ${d.talk_20_to_30_minutes?'✓':'—'} · 问题单 ${d.question_sheet?'✓':'—'}`}return`书面连续达标 ${mastery.written_streak||0}/3 · 口头四项 ${mastery.oral_met?'均 ≥4/5':'待达标'}`}
function renderGoalOverview(data){const p=data.portfolio||{},week=data.current_week||{},throughput=data.throughput||{},execution=data.execution||{},model=data.model||{};$('#goalTitle').textContent=p.title||'长期目标';$('#goalVersion').textContent=`计划版本 v${data.plan_version}`;$('#goalModel').textContent=`${model.name||'模型待配置'} · ${model.reasoning_effort||'—'}`;$('#goalModel').classList.toggle('bad',model.configured===false);$('#goalPortfolio').innerHTML=`<article class="pixel-panel goal-portfolio-card main"><p class="eyebrow">PORTFOLIO</p><h3>${escapeHtml(p.title||'')}</h3><p>${escapeHtml(p.institution||'')} · ${escapeHtml(p.direction||'')}</p><p>目标日期 ${escapeHtml(p.target_date||'待确认')} · 灰度试运行至 ${escapeHtml(p.trial_ends_on||'—')}</p></article><article class="pixel-panel goal-portfolio-card"><span>正常周容量</span><strong>${goalMinutes(p.capacity_min_minutes)}–${goalMinutes(p.capacity_max_minutes)}</strong><p>只统计深度学习。</p></article><article class="pixel-panel goal-portfolio-card"><span>当前周承诺</span><strong>${goalMinutes(week.deep_minutes)}</strong><p>${week.items?.length||0} 个本周池任务。</p></article><article class="pixel-panel goal-portfolio-card"><span>近三周执行</span><strong>${execution.status==='known'?goalRatio(execution.rate):'未知'}</strong><p>${escapeHtml(throughput.reason||'正在积累可比数据。')}</p></article>`;$('#goalTrackGrid').innerHTML=(data.tracks||[]).map(track=>`<article class="pixel-panel goal-track tone-${escapeHtml(track.status||'unknown')}"><div class="goal-track-head"><div><p class="eyebrow">${Math.round((track.weight||0)*100)}% RESOURCE</p><h3>${escapeHtml(track.title)}</h3></div><span class="goal-tone">${goalToneLabels[track.status]||track.status||'待核验'}</span></div><p class="goal-track-detail">${escapeHtml(track.outcome_definition||'')}</p><div class="goal-track-metrics"><span>内容覆盖<b>${goalRatio(track.content_coverage?.ratio)}</b></span><span>真实周执行<b>${goalRatio(track.weekly_execution?.rate)}</b></span><span>吞吐量预测<b>${track.throughput_forecast?.status==='known'?goalMinutes(track.throughput_forecast.weekly_minutes):'未知'}</b></span><span>证据置信度<b>${({unknown:'未知',low:'低',medium:'中',high:'高'})[track.evidence_confidence]||'未知'}</b></span><span>证据数量<b>${track.evidence_count||0}</b></span></div><p class="goal-track-detail">${goalTrackDetail(track)}</p></article>`).join('');const forecast=throughput.forecast_weekly_minutes===null||throughput.forecast_weekly_minutes===undefined?'未知':goalMinutes(throughput.forecast_weekly_minutes);$('#goalThroughput').innerHTML=`<div><p class="eyebrow">THROUGHPUT FORECAST</p><h3>${throughput.status==='known'?'最近两周真实吞吐量':'预测暂不可用'}</h3><p>${escapeHtml(throughput.reason||'')}</p></div><strong>${forecast}</strong>`}
function goalFeedbackKindForItem(item){if(!item)return'exercise';if(item.course_id)return item.input_state==='awaiting_course_progress'?'course':(/证明|复述/.test(item.title||'')?'proof':'exercise');if(item.track_code==='amss_exam')return'mock';if(item.track_code==='ergodic')return/讲解/.test(item.title||'')?'talk':/问题/.test(item.title||'')?'reading':'reading';if(item.track_code==='algebra')return/口头/.test(item.title||'')?'oral':'exercise';return'exercise'}
function goalTrackForKind(kind){return({course:'track-courses',grade:'track-courses',mock:'track-amss-exam',reading:'track-ergodic',talk:'track-ergodic',oral:'track-algebra'}[kind]||'track-courses')}
function openGoalFeedback(itemId='',kind='',course=''){goalView('evidence');const data=state.goal.data||{},items=data.current_week?.items||[],item=items.find(value=>value.id===itemId);const select=$('#goalFeedbackItem');if(select)select.value=itemId||'';const type=$('#goalFeedbackType'),selectedKind=kind||goalFeedbackKindForItem(item);if(type)type.value=selectedKind;$('#goalFeedbackTrack').value=item?.track_id||goalTrackForKind(selectedKind);goalQuickCourse=course||item?.course_id&&((data.course_profiles||[]).find(profile=>profile.id===item.course_id)?.name)||'';renderGoalQuickForm(data);requestAnimationFrame(()=>$('#goal-view-evidence')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function renderGoalWeek(data){if(window.renderCourseSchedule&&data.course_schedule)window.renderCourseSchedule($("#goalCourseSchedule"),data.course_schedule);const items=data.current_week?.items||[];$('#goalWeekList').innerHTML=items.length?items.map(item=>{const inputLabel=goalInputLabels[item.input_state]||item.input_state||'待核验';const sync=item.sync_status?` · ${item.sync_status==='queued'?'等待 Obsidian 写回':item.sync_status==='synced'?'已同步任务':'任务已完成'}`:'';const disabled=item.task_id||item.status==='completed'||item.input_state!=='ready';const action=item.task_id?'已进入任务系统':item.status==='completed'?'已完成':item.input_state!=='ready'?inputLabel:'确认这一天';return`<article class="pixel-panel goal-week-item ${item.input_state!=='ready'?'is-waiting':''}"><div><p class="eyebrow">${escapeHtml(item.track_title||item.track_code||'TRACK')}</p><h3>${escapeHtml(item.title)}</h3><div class="goal-week-meta"><span>${goalMinutes(item.deep_minutes)}</span><span>${goalStatusLabels[item.status]||item.status}</span><span>${escapeHtml(inputLabel)}</span><span>推荐 ${goalDate(item.recommended_date)}</span>${item.accepted_date?`<span>已确认 ${goalDate(item.accepted_date)}</span>`:''}</div><p>${escapeHtml(item.description||'')}${escapeHtml(sync)}</p></div><div class="goal-day-action"><button type="button" class="goal-feedback-action" data-goal-feedback="${escapeHtml(item.id)}">记进度</button><input type="date" value="${escapeHtml(item.accepted_date||item.recommended_date||'')}" data-goal-date="${escapeHtml(item.id)}" ${disabled?'disabled':''}><button type="button" data-goal-accept="${escapeHtml(item.id)}" ${disabled?'disabled':''}>${escapeHtml(action)}</button></div></article>`}).join(''):'<article class="pixel-panel goal-section-head"><p>当前没有周任务；请先完整复盘或等待下一个计划周。</p></article>';$$('[data-goal-accept]').forEach(button=>button.onclick=()=>acceptGoalDay(button.dataset.goalAccept,button));$$('[data-goal-feedback]').forEach(button=>button.onclick=()=>openGoalFeedback(button.dataset.goalFeedback))}
function renderGoalRoute(plan){$('#goalMilestones').innerHTML=(plan.milestones||[]).map(item=>`<article class="pixel-panel goal-milestone"><time>${escapeHtml(item.period_start)}<br>→ ${escapeHtml(item.period_end)}</time><div><h3>${escapeHtml(item.title)}</h3><ul>${(item.acceptance||[]).map(line=>`<li>${escapeHtml(line)}</li>`).join('')}</ul></div></article>`).join('')}
function goalAssessmentText(weights){const labels={midterm:'期中',final:'期末',homework:'作业',thinking_problems:'思考题',coursework:'平时'};return Object.entries(weights||{}).map(([key,value])=>`${labels[key]||key} ${Math.round(Number(value)*100)}%`).join(' · ')||'待核验'}
function renderGoalCourseProfiles(data){const progress=data.course_progress?.by_course||{};$('#goalCourseProfileGrid').innerHTML=(data.course_profiles||[]).map(profile=>{const p=progress[profile.name]||{},distribution=p.mastery_distribution||{};const status=profile.confirmation_status==='confirmed'?'已确认':'部分确认';return`<article class="pixel-panel goal-course-profile"><div class="goal-course-profile-head"><div><p class="eyebrow">${escapeHtml(profile.course_code||'COURSE')}</p><h3>${escapeHtml(profile.name)}</h3></div><span>${status}</span></div><p>${escapeHtml(profile.teacher||'教师待核验')} · ${escapeHtml((profile.textbooks||[])[0]||'教材待核验')}</p><p>${escapeHtml(goalAssessmentText(profile.assessment_weights))}</p><div class="goal-course-mastery"><span>授课小节<b>${p.confirmed_taught_units||0}/${p.total_units||0}</b></span><span>掌握 2<b>${distribution['2']||0}</b></span><span>掌握 3<b>${distribution['3']||0}</b></span><span>考试日期<b>${profile.exam_date?goalDate(profile.exam_date):'未知'}</b></span></div>${profile.hours_warning?`<p class="goal-course-warning">${escapeHtml(profile.hours_warning)}</p>`:''}<button type="button" class="goal-course-record" data-goal-course-record="${escapeHtml(profile.name)}">记录上课</button></article>`}).join('');$$('[data-goal-course-record]').forEach(button=>button.onclick=()=>openGoalFeedback('','course',button.dataset.goalCourseRecord))}
let goalQuickChoices={},goalQuickCourse='';
const goalQuickOptions={result:[['done','完成'],['partial','完成一部分'],['blocked','卡住']],assistance:[['none','全程独立'],['hint','用了提示'],['solution','看了解答'],['mixed','各题不同'],['unknown','未记录']],verification:[['reference','对照解答'],['human','他人核对'],['self','自己判断'],['unchecked','未核对']],basis:[['lecture','听课感受'],['recall','合书回忆'],['practice','题目 / 证明检验'],['unknown','暂不评估']],error:[['concept','概念 / 条件'],['strategy','没找到思路'],['proof','推导 / 证明'],['calculation','计算失误'],['unknown','暂不清楚']]};
function goalQuickButtons(key,items){return`<div class="goal-quick-options" data-goal-quick-group="${key}">${items.map(item=>`<button type="button" data-goal-quick-choice="${key}" data-value="${item[0]}" aria-pressed="${goalQuickChoices[key]===item[0]?'true':'false'}">${escapeHtml(item[1])}</button>`).join('')}</div>`}
function goalQuickGroup(label,key,items){return`<fieldset><legend>${escapeHtml(label)}</legend>${goalQuickButtons(key,items)}</fieldset>`}
function goalQuickNumber(id,label,placeholder='',max=10000){return`<label>${escapeHtml(label)}<input id="${id}" type="number" inputmode="decimal" min="0" max="${max}" step="any" placeholder="${escapeHtml(placeholder)}"></label>`}
function goalQuickValue(id){const element=$(`#${id}`);return element&&element.value!==''?element.value:null}
function renderGoalCourseUnitPicker(data){const course=$('#goalFeedbackCourse')?.value||goalQuickCourse,progress=data.course_progress?.by_course?.[course],root=$('#goalCourseUnitPicker');if(!root)return;if(!course||!progress){root.innerHTML='<p class="setting-help">先选择课程。</p>';return}const groups=new Map();(progress.units||[]).forEach(unit=>{const key=`${unit.chapter_no}. ${unit.chapter_title}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(unit)});root.innerHTML=[...groups.entries()].map(([chapter,units],index)=>`<details ${index===0?'open':''}><summary>${escapeHtml(chapter)}</summary><div class="goal-course-unit-group">${units.map(unit=>`<label class="goal-course-unit"><input type="checkbox" data-goal-course-unit="${escapeHtml(unit.id)}"><span>${escapeHtml(`${unit.chapter_no}.${unit.section_no} ${unit.title}`)}</span><select data-goal-course-mastery="${escapeHtml(unit.id)}" disabled>${Object.entries(goalMasteryLabels).map(([level,label])=>`<option value="${level}">${escapeHtml(label)}</option>`).join('')}</select></label>`).join('')}</div></details>`).join('');$$('[data-goal-course-unit]').forEach(box=>box.onchange=()=>{const select=$(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`);if(select){select.disabled=!box.checked;if(box.checked&&goalQuickChoices.common_mastery!==undefined)select.value=goalQuickChoices.common_mastery}})}
function goalQuickCourses(data){return`<label>课程<select id="goalFeedbackCourse"><option value="">请选择</option>${(data.course_profiles||[]).map(profile=>`<option value="${escapeHtml(profile.name)}" ${profile.name===goalQuickCourse?'selected':''}>${escapeHtml(profile.name)}</option>`).join('')}</select></label>`}
function renderGoalGradeComponents(data){const root=$('#goalGradeComponentPicker');if(!root)return;const course=$('#goalFeedbackCourse')?.value||goalQuickCourse,profile=(data.course_profiles||[]).find(item=>item.name===course),labels={midterm:'期中',final:'期末',homework:'作业',thinking_problems:'思考题',coursework:'平时'};const weights=Object.entries(profile?.assessment_weights||{});root.innerHTML=weights.length?`<label>考核项目<select id="goalQuickComponent"><option value="">请选择</option>${weights.map(([key,value])=>`<option value="${escapeHtml(key)}" data-weight="${Number(value)}">${escapeHtml(labels[key]||key)} · ${Math.round(Number(value)*100)}%</option>`).join('')}</select></label>`:'<label>考核项目<input id="goalQuickComponent" maxlength="100" placeholder="考核比例尚未确认"></label><p class="setting-help">没有确认比例时只保存原始成绩，不计算总评情景。</p>'}
function renderGoalQuickAdaptive(){const root=$('#goalQuickAdaptive'),kind=$('#goalFeedbackType').value;let html='';if(kind==='exercise'&&['hint','solution','mixed'].includes(goalQuickChoices.assistance))html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickNumber('goalQuickIndependent','其中独立做对几题？','无法区分可留空')}`;else if(kind==='exercise'&&goalQuickChoices.assistance==='none'&&goalQuickValue('goalQuickCorrect')!==null&&Number(goalQuickValue('goalQuickCorrect'))<Number(goalQuickValue('goalQuickAttempted')))html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickGroup('这次最主要的失误','diagnostic',goalQuickOptions.error)}`;else if(kind==='proof'&&goalQuickChoices.proof_result&&goalQuickChoices.proof_result!=='independent')html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickGroup('最需要补的环节','diagnostic',[['hypothesis','理解假设'],['construction','关键构造'],['deduction','推导细节'],['boundary','边界 / 反例'],['unknown','不确定']])}`;root.innerHTML=html;root.classList.toggle('hidden',!html);bindGoalQuickChoices(root)}
function bindGoalQuickChoices(scope=document){scope.querySelectorAll('[data-goal-quick-choice]').forEach(button=>button.onclick=()=>{const key=button.dataset.goalQuickChoice;goalQuickChoices[key]=button.dataset.value;scope.querySelectorAll(`[data-goal-quick-choice="${CSS.escape(key)}"]`).forEach(peer=>peer.setAttribute('aria-pressed',String(peer===button)));if(key==='common_mastery'){$$('[data-goal-course-unit]:checked').forEach(box=>{const select=$(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`);if(select)select.value=button.dataset.value})}if(['assistance','proof_result'].includes(key))renderGoalQuickAdaptive()})}
function renderGoalQuickForm(data){goalQuickChoices={};const kind=$('#goalFeedbackType').value,root=$('#goalQuickFields');let html='';if(kind==='course'){html=goalQuickCourses(data)+`<section id="goalCourseProgressFields" class="goal-course-progress-fields"><div><h3>确认实际讲到的小节</h3><p class="setting-help">勾选小节；共同掌握度可一次应用，再按小节改动。</p></div><div id="goalCourseUnitPicker" class="goal-course-unit-picker"></div>${goalQuickGroup('所选小节共同掌握度','common_mastery',Object.entries(goalMasteryLabels))}${goalQuickGroup('这次掌握度依据','basis',goalQuickOptions.basis)}</section>`}else if(kind==='exercise'){html=`<div class="goal-form-grid">${goalQuickNumber('goalQuickAttempted','尝试题数','例如 10')}${goalQuickNumber('goalQuickCorrect','最终做对','未核对可留空')}</div>${goalQuickGroup('完成情况','result',goalQuickOptions.result)}${goalQuickGroup('解题时用了多少帮助？','assistance',goalQuickOptions.assistance)}${goalQuickGroup('正确数怎么核对？','verification',goalQuickOptions.verification)}<label>题组 / 来源<input id="goalQuickSource" maxlength="160" placeholder="如：作业1第1–10题；代数书面任务必填"></label>`}else if(kind==='proof'){html=`${goalQuickGroup('这次能做到','proof_result',[['independent','独立完成'],['hinted','提示后完成'],['partial','只完成一部分'],['blocked','尚未完成']])}${goalQuickGroup('本次属于','attempt_timing',[['first','首次尝试'],['immediate','即时重做'],['delayed','隔日复测'],['unknown','不确定']])}${goalQuickGroup('怎么核对？','verification',goalQuickOptions.verification)}<label>命题 / 证明对象<input id="goalQuickObject" maxlength="200" placeholder="自动关联不准确时补充"></label>`}else if(kind==='grade'){html=`${goalQuickCourses(data)}<div id="goalGradeComponentPicker"></div><div class="goal-form-grid">${goalQuickNumber('goalQuickScore','得分','真实值')}${goalQuickNumber('goalQuickMax','满分','例如 100')}</div>${goalQuickGroup('成绩来源','origin',[['official','老师 / 教务公布'],['self','对照标准自评'],['estimate','暂时估分']])}` }else if(kind==='mock'){html=`<label>真实题源 / 试卷 ID<input id="goalQuickSource" maxlength="160" placeholder="不同卷必须使用不同 ID"></label><div class="goal-form-grid">${goalQuickNumber('goalQuickScore','得分','未批改可留空',150)}${goalQuickNumber('goalQuickMax','满分','例如 150',150)}${goalQuickNumber('goalQuickElapsed','实际用时（分钟）','例如 120',1440)}</div>${goalQuickGroup('作答帮助','assistance',goalQuickOptions.assistance)}${goalQuickGroup('完成条件','condition',[['timed','完整限时'],['interrupted','有中断'],['untimed','非限时'],['unknown','未记录']])}${goalQuickGroup('题目熟悉度','novelty',[['new','首次见'],['repeat','做过 / 看过'],['mixed','部分见过'],['unknown','不确定']])}${goalQuickGroup('评分依据','verification',goalQuickOptions.verification)}` }else if(kind==='reading'){html=`${goalQuickGroup('本次进展','result',goalQuickOptions.result)}${goalQuickGroup('实际检验到哪一步？','quality',[['summary','能合书讲主线'],['proof','能重建关键证明'],['apply','能用于新例子'],['untested','还没有检验']])}${goalQuickNumber('goalQuickUnits','新增笔记页数（可选）','未统计可留空')}` }else if(kind==='talk'){html=`${goalQuickNumber('goalQuickUnits','实际讲解分钟','例如 20',1440)}${goalQuickGroup('讲解情况','talk_result',[['independent','连贯讲完'],['notes','频繁看笔记'],['blocked','没有讲完']])}${goalQuickGroup('追问表现','questions',[['independent','独立答出'],['hinted','提示后答出'],['failed','没有答出'],['untested','没有追问']])}${goalQuickGroup('评价者','rater',[['self','自己'],['peer','同学 / 老师'],['unknown','未评价']])}` }else if(kind==='oral'){html=`<p class="setting-help">四项 0–5；未测请选择“—”。</p><div class="goal-oral-grid">${['定义','例子','策略','追问'].map((label,index)=>`<label>${label}<select data-goal-oral="${index}"><option value="">—</option>${[0,1,2,3,4,5].map(value=>`<option value="${value}">${value}</option>`).join('')}</select></label>`).join('')}</div>${goalQuickGroup('评分者','rater',[['self','自己'],['peer','同学 / 老师'],['ai','AI 辅助']])}${goalQuickGroup('回答条件','assistance',[['none','独立回答'],['hint','有提示'],['solution','看了材料'],['unknown','未记录']])}` }else{html=`${goalQuickGroup('主要原因','blocked_reason',[['concept','概念不清'],['proof','证明卡住'],['material','缺资料'],['time','时间不足'],['other','其他']])}${goalQuickGroup('影响范围','impact',[['local','一个步骤'],['session','本次做不下去'],['recurring','多次反复'],['unknown','不确定']])}${goalQuickGroup('希望怎么处理','request',[['split','拆小任务'],['explain','补解释 / 前置'],['defer','重新建议日期']])}` }root.innerHTML=html;bindGoalQuickChoices(root);$('#goalFeedbackCourse')?.addEventListener('change',event=>{goalQuickCourse=event.target.value;if(kind==='course')renderGoalCourseUnitPicker(data);if(kind==='grade')renderGoalGradeComponents(data)});if(kind==='course')renderGoalCourseUnitPicker(data);if(kind==='grade')renderGoalGradeComponents(data);root.querySelectorAll('input').forEach(input=>input.addEventListener('input',renderGoalQuickAdaptive));renderGoalQuickAdaptive()}
function renderGoalEvidence(data){const items=data.current_week?.items||[];renderGoalCourseProfiles(data);const itemSelect=$('#goalFeedbackItem'),selectedItem=itemSelect.value;itemSelect.innerHTML='<option value="">不关联具体任务</option>'+items.map(item=>`<option value="${escapeHtml(item.id)}" data-track="${escapeHtml(item.track_id)}">${escapeHtml(item.title)}</option>`).join('');if(selectedItem&&items.some(item=>item.id===selectedItem))itemSelect.value=selectedItem;const selected=items.find(item=>item.id===itemSelect.value);$('#goalFeedbackTrack').value=selected?.track_id||$('#goalFeedbackTrack').value||'track-courses';const materials=data.materials||{};$('#goalMaterialGaps').innerHTML=`<div class="goal-mini-list">${(materials.gaps||[]).map(gap=>`<p>${escapeHtml(gap)}</p>`).join('')||'<p>暂无资料缺口。</p>'}<p>授权入口：${escapeHtml(materials.manifest_path||'目标模式资料清单.md')}</p></div>`;$('#goalMaterialDocs').innerHTML=`<div class="goal-mini-list">${(materials.documents||[]).map(doc=>{const meta=doc.metadata||{},kind=meta.note_format==='mathink_markdown'?'MathInk 可见层':meta.note_format||'';return`<p><b>${escapeHtml(doc.title)}</b><br>${doc.page_count||'—'} 页 · ${escapeHtml(doc.status||'')} ${kind?`· ${escapeHtml(kind)}`:''}</p>`}).join('')||'<p>尚未索引授权资料；勾选清单后由 Windows 导出器分页提取。</p>'}</div>`;$('#goalSources').innerHTML=`<div class="goal-mini-list">${(data.sources||[]).map(source=>source.url?`<a href="${escapeHtml(source.url)}" target="_blank" rel="noopener"><b>${escapeHtml(source.grade)}</b> · ${escapeHtml(source.title)}${source.reference_only?'（往届参考）':''}</a>`:`<p>${escapeHtml(source.title)}</p>`).join('')}</div>`;renderGoalQuickForm(data)}
function renderGoalChat(data){const messages=data.chat_messages||[],model=data.model||{};$('#goalChatList').innerHTML=messages.length?messages.map(item=>`<div class="goal-chat-message ${item.role==='user'?'user':'assistant'}">${escapeHtml(item.content)}<small>${formatTime(item.created_at)}</small></div>`).join(''):'<p class="setting-help">尚无沟通记录。可以反馈策略疑问；目标 Agent 可能自动调整同月短期计划。</p>';const list=$('#goalChatList');list.scrollTop=list.scrollHeight;const boundary=data.boundaries||{};$('#goalBoundaries').innerHTML=`<p class="setting-help">Next Action 与目标 Agent 是两个功能。</p><p class="setting-help">当前模型：${escapeHtml(model.name||'待配置')} · Responses · ${escapeHtml(model.reasoning_effort||'—')}。模型不可用时只保留确定性评估，不回退到 DeepSeek。</p><h3>可自动修改</h3><ul>${(boundary.automatic||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul><h3>必须确认</h3><ul>${(boundary.approval_required||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`}
function renderGoalHistory(data,plan){$('#goalApprovals').innerHTML=`<div class="goal-history-list">${(data.approvals||[]).map(item=>`<div class="goal-history-row"><h3>${escapeHtml(item.change_type)}</h3><p>${escapeHtml(item.reason)}</p><p>变更字段：${escapeHtml(Object.keys(item.patch||{}).join('、')||'—')}</p><div class="goal-history-actions"><button data-goal-approval="${escapeHtml(item.id)}" data-decision="approved">批准</button><button class="reject" data-goal-approval="${escapeHtml(item.id)}" data-decision="rejected">拒绝</button></div></div>`).join('')||'<p class="setting-help">没有待确认重大修改。</p>'}</div>`;$$('[data-goal-approval]').forEach(button=>button.onclick=()=>decideGoalApproval(button.dataset.goalApproval,button.dataset.decision,button));$('#goalVersions').innerHTML=`<div class="goal-history-list">${(plan.versions||[]).map(version=>`<div class="goal-history-row"><h3>v${version.id} · ${escapeHtml(version.reason)}</h3><p>${formatTime(version.created_at)} · ${escapeHtml(version.actor||'system')} · ${escapeHtml(version.trigger||'')}</p><p>${(version.changes||[]).length} 项差异${version.rollback_of?` · 回退自 v${version.rollback_of}`:''}</p><div class="goal-history-actions"><button data-goal-rollback="${version.id}" ${version.id===data.plan_version?'disabled':''}>回退到此版本</button></div></div>`).join('')||'<p class="setting-help">尚无版本历史。</p>'}</div>`;$$('[data-goal-rollback]').forEach(button=>button.onclick=()=>rollbackGoalVersion(Number(button.dataset.goalRollback),button))}
function renderGoalMode(){const data=state.goal.data,plan=state.goal.plan;if(!data||!plan)return;renderGoalOverview(data);renderGoalWeek(data);renderGoalRoute(plan);renderGoalEvidence(data);renderGoalChat(data);renderGoalHistory(data,plan);goalView(state.goal.view);goalSetStatus(`已加载 ${formatTime(data.generated_at)} · ${data.current_week?.week_start||'未建立周计划'} 起共 ${goalMinutes(data.current_week?.deep_minutes||0)}。`)}
async function loadGoalMode(){goalSetStatus('正在读取长期目标、计划版本和证据…');try{const [data,plan]=await Promise.all([api('/api/goal-agent/state'),api('/api/goal-agent/plan')]);state.goal.data=data;state.goal.plan=plan;renderGoalMode()}catch(error){goalSetStatus(`目标模式暂不可用：${error.message}`,true);toast('目标模式读取失败',true)}}
async function goalWrite(path,body,prefix){if(!state.goal.data)await loadGoalMode();const payload={request_id:goalRequestId(prefix),base_plan_version:state.goal.data.plan_version,...body};try{return await api(path,{method:'POST',body:JSON.stringify(payload)})}catch(error){if(error.status===409){await loadGoalMode();throw new Error('计划刚被另一项操作更新，已刷新最新版本，请重试。')}throw error}}
async function acceptGoalDay(id,button){const input=$(`[data-goal-date="${CSS.escape(id)}"]`);if(!input?.value){toast('请先选择日期',true);return}button.disabled=true;try{await goalWrite(`/api/goal-agent/plan-items/${encodeURIComponent(id)}/accept-day`,{date:input.value},'day');toast('已排入任务同步队列；等待 Obsidian 快照确认');await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false}}
function optionalNumber(selector){const value=$(selector)?.value;return value===''||value===undefined?null:Number(value)}
function goalQuickRequired(kind,keys){const missing=keys.find(key=>!goalQuickChoices[key]);if(missing){toast('请补选本次表现条件；未知可以明确选择。',true);return false}return true}
async function submitGoalFeedback(){const button=$('#goalFeedbackSubmit'),kind=$('#goalFeedbackType').value,itemId=$('#goalFeedbackItem').value||null,item=(state.goal.data?.current_week?.items||[]).find(value=>value.id===itemId),trackId=item?.track_id||$('#goalFeedbackTrack').value||goalTrackForKind(kind);let evidenceType='progress_update',score=null,maxScore=null,completedUnits=null,sourceId=null,blockedReason=null;const details={feedback_schema_version:2,feedback_kind:kind,performance:{},conditions:{},note:$('#goalFeedbackNote').value.trim()||null};if(kind==='course'){evidenceType='course_progress';const course=$('#goalFeedbackCourse').value,selected=$$('[data-goal-course-unit]:checked');if(!course||!selected.length||!goalQuickRequired(kind,['common_mastery','basis'])){if(!course||!selected.length)toast('请选择课程和实际讲到的小节。',true);return}details.course=course;details.taught_units=selected.map(box=>({unit_id:box.dataset.goalCourseUnit,mastery:Number($(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`).value)}));details.conditions.mastery_basis=goalQuickChoices.basis}else if(kind==='exercise'){if(!goalQuickRequired(kind,['result','assistance','verification']))return;const attempted=Number(goalQuickValue('goalQuickAttempted')),correctRaw=goalQuickValue('goalQuickCorrect'),correct=correctRaw===null?null:Number(correctRaw),independentRaw=goalQuickValue('goalQuickIndependent'),independent=independentRaw===null?null:Number(independentRaw);if(!Number.isInteger(attempted)||attempted<1||correct!==null&&(!Number.isInteger(correct)||correct<0||correct>attempted)||independent!==null&&(!Number.isInteger(independent)||independent<0||correct===null||independent>correct)){toast('请检查题数：尝试数至少 1，且独立做对 ≤ 最终做对 ≤ 尝试数。',true);return}evidenceType=item?.track_code==='algebra'?'algebra_written':'progress_update';details.performance={attempted,correct,independent_correct:goalQuickChoices.assistance==='none'?correct:independent,result:goalQuickChoices.result,error_type:goalQuickChoices.diagnostic||null};details.conditions={assistance:goalQuickChoices.assistance,verification:goalQuickChoices.verification};completedUnits=attempted;sourceId=goalQuickValue('goalQuickSource');if(evidenceType==='algebra_written'){if(!sourceId){toast('代数书面任务需要题组 / 来源 ID，避免重复题被计为连续达标。',true);return}score=correct;maxScore=attempted}}else if(kind==='proof'){if(!goalQuickRequired(kind,['proof_result','attempt_timing','verification']))return;details.performance={result:goalQuickChoices.proof_result,weak_step:goalQuickChoices.diagnostic||null,object:goalQuickValue('goalQuickObject')};details.conditions={attempt_timing:goalQuickChoices.attempt_timing,verification:goalQuickChoices.verification}}else if(kind==='grade'){if(!goalQuickRequired(kind,['origin']))return;evidenceType='course_component';score=Number(goalQuickValue('goalQuickScore'));maxScore=Number(goalQuickValue('goalQuickMax'));const course=$('#goalFeedbackCourse').value,component=$('#goalQuickComponent'),componentValue=component?.value||'',selectedOption=component?.selectedOptions?.[0],weight=selectedOption?.dataset?.weight===''||selectedOption?.dataset?.weight===undefined?null:Number(selectedOption.dataset.weight);if(!course||!componentValue){toast('请选择课程和考核项目。',true);return}if(!Number.isFinite(score)||!Number.isFinite(maxScore)||maxScore<=0||score<0||score>maxScore){toast('请填写有效得分和满分。',true);return}details.course=course;details.component=componentValue;if(Number.isFinite(weight))details.weight=weight;details.conditions={origin:goalQuickChoices.origin}}else if(kind==='mock'){if(!goalQuickRequired(kind,['assistance','condition','novelty','verification']))return;evidenceType='exam_mock';sourceId=goalQuickValue('goalQuickSource');if(!sourceId){toast('请选择或填写真实题源。',true);return}const scoreRaw=goalQuickValue('goalQuickScore'),maxRaw=goalQuickValue('goalQuickMax');score=scoreRaw===null?null:Number(scoreRaw);maxScore=maxRaw===null?null:Number(maxRaw);if((score===null)!==(maxScore===null)||score!==null&&(!Number.isFinite(score)||!Number.isFinite(maxScore)||maxScore<=0||score<0||score>maxScore)){toast('得分与满分请同时填写，并检查范围。',true);return}details.performance={elapsed_minutes:goalQuickValue('goalQuickElapsed')===null?null:Number(goalQuickValue('goalQuickElapsed'))};details.conditions={assistance:goalQuickChoices.assistance,completion:goalQuickChoices.condition,novelty:goalQuickChoices.novelty,verification:goalQuickChoices.verification}}else if(kind==='reading'){if(!goalQuickRequired(kind,['result','quality']))return;evidenceType='ergodic_note';completedUnits=goalQuickValue('goalQuickUnits')===null?null:Number(goalQuickValue('goalQuickUnits'));details.performance={result:goalQuickChoices.result,quality_check:goalQuickChoices.quality}}else if(kind==='talk'){if(!goalQuickRequired(kind,['talk_result','questions','rater']))return;evidenceType='ergodic_talk';completedUnits=Number(goalQuickValue('goalQuickUnits'));if(!Number.isFinite(completedUnits)||completedUnits<=0){toast('请填写有效讲解分钟。',true);return}details.performance={result:goalQuickChoices.talk_result,questions:goalQuickChoices.questions};details.conditions={rater:goalQuickChoices.rater}}else if(kind==='oral'){if(!goalQuickRequired(kind,['rater','assistance']))return;evidenceType='algebra_oral';const values=$$('[data-goal-oral]').map(select=>select.value===''?null:Number(select.value));if(values.every(value=>value===null)){toast('请至少填写一项口头测评。',true);return}details.oral_scores={definition:values[0],example:values[1],strategy:values[2],follow_up:values[3]};details.conditions={rater:goalQuickChoices.rater,assistance:goalQuickChoices.assistance}}else{if(!goalQuickRequired(kind,['blocked_reason','impact','request']))return;blockedReason=goalQuickChoices.blocked_reason;details.performance={impact:goalQuickChoices.impact};details.conditions={requested_response:goalQuickChoices.request}}const body={track_id:trackId,plan_item_id:itemId,evidence_type:evidenceType,deep_minutes:optionalNumber('#goalFeedbackMinutes'),status:$('#goalFeedbackStatus').value||null,score,max_score:maxScore,completed_units:completedUnits,source_id:sourceId,blocked_reason:blockedReason,details};button.disabled=true;try{const result=await goalWrite('/api/goal-agent/feedback',body,'feedback');const boundary=result.evidence_boundary||'证据已按原始条件保存；不足的部分保持待核验。';$('#goalEvidenceBoundary').textContent=boundary;toast('反馈已保存；AI 复盘将结合历史与资料，不会把单次自评当成完整结论');$('#goalFeedbackNote').value='';await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false}}
async function sendGoalChat(){const button=$('#goalChatSend'),message=$('#goalChatInput').value.trim();if(!message){toast('请先写要沟通的内容',true);return}button.disabled=true;button.textContent='目标 Agent 正在评估…';try{const result=await goalWrite('/api/goal-agent/chat',{message},'chat');$('#goalChatInput').value='';toast(result.model_status==='failed'?'已记录，但本次模型暂不可用':'目标 Agent 已回复并完成权限内调整',result.model_status==='failed');await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='发送给目标 Agent'}}
async function runGoalReview(){const button=$('#goalReview');button.disabled=true;button.textContent='正在完整复盘…';goalSetStatus('正在汇总证据、检索资料并评估计划；可能需要约一分钟。');try{const result=await goalWrite('/api/goal-agent/review',{},'review');toast(result.model_status==='failed'?'确定性复盘已完成；AI 模型本次不可用':'完整复盘已生成');await loadGoalMode()}catch(error){toast(error.message,true);goalSetStatus(error.message,true)}finally{button.disabled=false;button.textContent='立即完整复盘'}}
async function decideGoalApproval(id,decision,button){button.disabled=true;try{await goalWrite(`/api/goal-agent/approvals/${encodeURIComponent(id)}/decision`,{decision},'approval');toast(decision==='approved'?'重大修改已批准并生成新版本':'已拒绝重大修改');await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false}}
async function rollbackGoalVersion(version,button){if(!confirm(`回退到计划版本 v${version}？当前版本不会被删除，会生成一条新的回退版本。`))return;button.disabled=true;try{await goalWrite(`/api/goal-agent/versions/${version}/rollback`,{},'rollback');toast(`已回退到 v${version} 的计划内容，并保留完整审计历史`);await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false}}
$$('[data-goal-view]').forEach(button=>button.onclick=()=>goalView(button.dataset.goalView));
$('#goalReview').onclick=runGoalReview;
$('#goalFeedbackSubmit').onclick=submitGoalFeedback;
$('#goalChatSend').onclick=sendGoalChat;
$('#goalFeedbackItem').onchange=event=>{const item=(state.goal.data?.current_week?.items||[]).find(value=>value.id===event.target.value);if(item){$('#goalFeedbackTrack').value=item.track_id;$('#goalFeedbackType').value=goalFeedbackKindForItem(item);goalQuickCourse=item.course_id&&((state.goal.data.course_profiles||[]).find(profile=>profile.id===item.course_id)?.name)||''}renderGoalQuickForm(state.goal.data||{})};$('#goalFeedbackType').onchange=event=>{if(!$('#goalFeedbackItem').value)$('#goalFeedbackTrack').value=goalTrackForKind(event.target.value);renderGoalQuickForm(state.goal.data||{})};
